  "res://scripts/audio_manager.gd": "extends Node

var _sfx_players = []
var _music_player: AudioStreamPlayer

func _ready():
	process_mode = Node.PROCESS_MODE_ALWAYS
	for i in 16:
		var p = AudioStreamPlayer.new()
		p.bus = "Master"
		add_child(p)
		_sfx_players.append(p)
	_music_player = AudioStreamPlayer.new()
	_music_player.bus = "Master"
	_music_player.volume_db = -10
	add_child(_music_player)

func play_sfx(type):
	var stream = _generate_sfx(type)
	if stream == null:
		return
	for p in _sfx_players:
		if not p.playing:
			p.stream = stream
			p.volume_db = randf_range(-3, 0)
			p.pitch_scale = randf_range(0.92, 1.08)
			p.play()
			return
	var p = _sfx_players[0]
	p.stream = stream
	p.play()

func play_music(track):
	var stream = _generate_music(track)
	if stream == null:
		return
	if _music_player.stream != null and _music_player.playing:
		_music_player.stop()
	_music_player.stream = stream
	_music_player.play()

func stop_music():
	if _music_player and _music_player.playing:
		_music_player.stop()

func _generate_sfx(type):
	var rate = 22050.0
	var duration = 0.15
	if type == "shoot":
		duration = 0.09
	elif type == "hit":
		duration = 0.2
	elif type == "explode":
		duration = 0.5
	elif type == "powerup":
		duration = 0.45
	elif type == "click":
		duration = 0.04
	elif type == "damage":
		duration = 0.25
	elif type == "gameover":
		duration = 1.2
	elif type == "wave":
		duration = 0.6
	elif type == "warning":
		duration = 0.5
	else:
		return null
	var frames = int(rate * duration)
	var stream = AudioStreamWAV.new()
	stream.mix_rate = rate
	stream.format = AudioStreamWAV.FORMAT_16_BITS
	stream.stereo = false
	var data = PackedByteArray()
	data.resize(frames * 2)
	var phase = 0.0
	var phase2 = 0.0
	for i in frames:
		var p = float(i) / rate
		var s = 0.0
		if type == "shoot":
			var f = lerp(1400.0, 220.0, p / duration)
			phase += f / rate
			s = sin(phase * TAU) * exp(-p * 28.0) * 0.6
		elif type == "hit":
			var f = lerp(900.0, 120.0, p / duration)
			phase += f / rate
			s = sin(phase * TAU) * exp(-p * 9.0) * 0.5
			s += (randf() * 2.0 - 1.0) * exp(-p * 18.0) * 0.4
		elif type == "explode":
			s = (randf() * 2.0 - 1.0) * exp(-p * 3.5) * (1.0 - p / duration) * 0.7
			s += sin(p * 70.0) * exp(-p * 7.0) * 0.3
		elif type == "powerup":
			var f = 440.0 + 800.0 * (p / duration)
			phase += f / rate
			s = sin(phase * TAU) * exp(-p * 2.5) * 0.6
		elif type == "click":
			s = sin(p * 1600.0) * exp(-p * 90.0) * 0.5
		elif type == "damage":
			s = (randf() * 2.0 - 1.0) * exp(-p * 6.0) * 0.8
