	if stream != null:
		_music_cache[track] = stream
	return stream

func _generate_sfx(type: String) -> AudioStreamWAV:
	var rate := 22050.0
	var duration := 0.15
	match type:
		"shoot":		duration = 0.09
		"hit":			duration = 0.2
		"explode":		duration = 0.5
		"powerup":		duration = 0.45
		"click":		duration = 0.04
		"damage":		duration = 0.25
		"gameover":		duration = 1.2
		"wave":			duration = 0.6
		"warning":		duration = 0.5
		_:
			return null

