				s += (randf() * 2.0 - 1.0) * exp(-p * 18.0) * 0.4
			"explode":
				s = (randf() * 2.0 - 1.0) * exp(-p * 3.5) * (1.0 - p / duration) * 0.7
				s += sin(p * 70.0) * exp(-p * 7.0) * 0.3
			"powerup":
