func _test_inspect_resource_interface(ei: EditorInterface) -> Dictionary:
	var test := {"name": "资源接口提取", "ok": false, "detail": "", "data": {}}

	# 测试 get_property_list() 反射能力
	# 用 StyleBoxFlat 作为测试对象（内置 Resource 类型）
	var res = ClassDB.instantiate("StyleBoxFlat")
	if res == null:
		test.detail = "无法实例化 StyleBoxFlat"
		return test

	var props: Array = []
	for p in res.get_property_list():
		var pname: String = p.get("name", "")
		var ptype: int = p.get("type", 0)
		var pusage: int = p.get("usage", 0)
		# 只收集有意义的属性（过滤内部属性和方法）
		if pname.begins_with("_"):
			continue
		if pusage & PROPERTY_USAGE_EDITOR == 0 and pusage & PROPERTY_USAGE_STORAGE == 0:
			continue
		if ptype == TYPE_NIL and pusage & PROPERTY_USAGE_GROUP:
			continue
		props.append({
			"name": pname,
			"type": type_string(ptype),
			"type_id": ptype,
			"value": str(res.get(pname)) if ptype != TYPE_NIL else "",
		})

	test.ok = props.size() > 10  # StyleBoxFlat 应该有很多属性
	test.detail = "StyleBoxFlat 有 %d 个可编辑属性" % props.size()
	test.data = {
		"class": "StyleBoxFlat",
		"property_count": props.size(),
		"sample_properties": props.slice(0, min(20, props.size())),
	}

	if test.ok:
		print("✅ %s: %s" % [test.name, test.detail])
	else:
		print("❌ %s: %s" % [test.name, test.detail])

	res = null
	return test


# ============ 辅助函数 ============

func _collect_nodes(root: Node, node: Node, out: Array, depth: int) -> void:
	var info: Dictionary = {
		"name": node.name,
		"type": node.get_class(),
		"path": str(root.get_path_to(node)) if node != root else ".",
		"depth": depth,
		"child_count": node.get_child_count(),
		"script": "",
		"signal_count": 0,
		"groups": node.get_groups(),
		"properties": {},
	}

	# 脚本
	var script = node.get_script()
	if script != null:
		var script_res = script as Resource
		if script_res != null:
			info.script = script_res.resource_path

	# 信号连接（编辑器绑定）
	var sig_count := 0
	for sig_info in node.get_signal_list():
		var sig_name: String = str(sig_info.get("name", ""))
		sig_count += node.get_signal_connection_list(sig_name).size()
	info.signal_count = sig_count

	# 关键属性（只收集有意义的，过滤默认值和内部属性）
	if node is Node2D:
		var n2d := node as Node2D
		if n2d.position != Vector2.ZERO:
			info.properties["position"] = [n2d.position.x, n2d.position.y]
		if n2d.rotation != 0:
			info.properties["rotation"] = n2d.rotation
		if n2d.scale != Vector2.ONE:
			info.properties["scale"] = [n2d.scale.x, n2d.scale.y]
		if n2d.z_index != 0:
			info.properties["z_index"] = n2d.z_index
	if node is CollisionObject2D:
		var co := node as CollisionObject2D
		info.properties["collision_layer"] = co.collision_layer
		info.properties["collision_mask"] = co.collision_mask
	if node is Control:
		var ctrl := node as Control
		if ctrl.layout_mode != 0:
			info.properties["layout_mode"] = ctrl.layout_mode
		if ctrl.anchors_preset != -1:
			info.properties["anchors_preset"] = ctrl.anchors_preset
	if node is Timer:
		var timer := node as Timer
		info.properties["wait_time"] = timer.wait_time
		info.properties["autostart"] = timer.autostart
	if node is Label:
		var label := node as Label
		if not label.text.is_empty():
			info.properties["text"] = label.text

	out.append(info)

	for child in node.get_children():
		_collect_nodes(root, child, out, depth + 1)


func _write_results(results: Array) -> void:
	var output := {
		"timestamp": Time.get_datetime_string_from_system(),
		"godot_version": Engine.get_version_info().get("string", ""),
		"test_count": results.size(),
		"passed": 0,
		"failed": 0,
		"results": results,
	}

	for r in results:
		if r.get("ok", false):
			output.passed += 1
		else:
			output.failed += 1

	var json := JSON.stringify(output, "  ")
	var f := FileAccess.open("res://tests/results.json", FileAccess.WRITE)
	if f:
		f.store_string(json)
		f.close()
		print("\n📁 结果已写入: res://tests/results.json")
		print("✅ %d 通过 / ❌ %d 失败 / 共 %d 测试" % [output.passed, output.failed, output.test_count])
	else:
		print("⚠️ 无法写入结果文件")

	# 同时写一份人类可读的摘要
	var summary := FileAccess.open("res://tests/results_summary.txt", FileAccess.WRITE)
	if summary:
		summary.store_string("Banyan Tool Test Results\n")
		summary.store_string("========================\n")
		summary.store_string("Time: %s\n" % output.timestamp)
		summary.store_string("Godot: %s\n" % output.godot_version)
		summary.store_string("Pass: %d / Fail: %d / Total: %d\n\n" % [output.passed, output.failed, output.test_count])
		for r in results:
			var icon := "✅" if r.ok else "❌"
			summary.store_string("%s %s\n" % [icon, r.name])
			summary.store_string("   %s\n" % r.detail)
			if not r.get("data", {}).get("errors", []).is_empty():
				for e in r.data.errors:
					summary.store_string("   ⚠️ %s\n" % e)
			summary.store_string("\n")
		summary.close()

@tool
extends EditorScript
## DotAgent Task Runner — 外部自动化入口
##
## 用法:
##   1. QoderWork 写任务到 res://dotagent_task.json
##   2. 运行: godot --script tests/run_task.gd
##   3. 结果写入 res://dotagent_result.json
##   4. QoderWork 读取结果
##
## 任务文件格式 (dotagent_task.json):
##   {"task": "用户消息文本", "max_rounds": 10}
##
## 结果文件格式 (dotagent_result.json):
##   {"ok": true, "content": "AI 最终回复", "rounds": 4, "tools_used": [...], "error": ""}

const TASK_PATH := "res://dotagent_task.json"
const RESULT_PATH := "res://dotagent_result.json"

# ============ Plugin Stub ============
# DockController 和 tools 需要一个有 get_editor_interface() 方法的对象
# EditorScript 自身就有这个方法，但我们不能直接传 self（EditorScript 不是 Node）
# 所以创建一个 RefCounted 代理

class PluginStub:
	var _ei: EditorInterface
	func _init(ei: EditorInterface) -> void:
		_ei = ei
	func get_editor_interface():
		return _ei


func _run() -> void:
	print("\n══════════════════════════════════════════════════")
	print("  DotAgent Task Runner")
	print("══════════════════════════════════════════════════\n")

	# 1. 读取任务
	var task_text := _read_task()
	if task_text.is_empty():
		_write_error("No task found at %s" % TASK_PATH)
		return

	print("  Task: %s\n" % task_text.substr(0, 200))

	# 2. 创建代理和宿主
	var ei := get_editor_interface()
	if ei == null:
		_write_error("EditorInterface not available")
		return

	var stub := PluginStub.new(ei)

	# 创建宿主 Node — LLMClient 需要在场景树中接收 _process()
	var host := Node.new()
	host.name = "TaskRunnerHost"
	# 添加到编辑器场景树
	var root = ei.get_edited_scene_root()
	if root:
		root.add_child(host)
		host.owner = root
	else:
		# 没有打开的场景 — 创建一个临时场景
		var temp_root := Node2D.new()
		temp_root.name = "TaskRunnerScene"
		var scene := PackedScene.new()
		scene.pack(temp_root)
		ei.open_scene_from_path("res://scenes/main.tscn")
		await Engine.get_main_loop().create_timer(0.2).timeout
		root = ei.get_edited_scene_root()
		if root:
			root.add_child(host)
			host.owner = root

	# 3. 初始化 DockController
	var controller := DockController.new()
	controller.setup(stub, null, host)
	controller.bootstrap_session()

	# 4. 连接信号用于追踪
	var rounds := 0
	var tools_used: Array = []
	var final_content := ""
	var error_msg := ""

	controller.round_complete.connect(func(content: String, tool_calls: Array, tool_results: Array):
		rounds += 1
		for tc in tool_calls:
			var fn: Dictionary = tc.get("function", {})
			var name: String = fn.get("name", "")
			if not name.is_empty() and name not in tools_used:
				tools_used.append(name)
		if not content.is_empty():
			final_content = content
		print("  Round %d: tools=%d content=%d chars" % [rounds, tool_calls.size(), content.length()])
	)

	controller.stream_error.connect(func(err: String):
		error_msg = err
		print("  ERROR: %s" % err)
	)

	# 5. 执行任务
	print("  Executing...\n")
	controller.send_user_message(task_text)

	# 6. 等待完成（send_user_message 是 async，但 EditorScript._run 不支持 await）
	# 用信号轮询等待
	var done := false
	controller.loop_finished.connect(func(): done = true)

	# EditorScript 的 _run() 不支持 await，所以用 process frame 轮询
	var max_wait := 300  # 最多等 300 秒
	var waited := 0.0
	while not done and waited < max_wait:
		await Engine.get_main_loop().create_timer(0.5).timeout
		waited += 0.5

	if not done:
		error_msg = "Timeout after %ds" % max_wait

	# 7. 清理
	host.queue_free()

	# 8. 写入结果
	var result := {
		"ok": error_msg.is_empty() and not final_content.is_empty(),
		"content": final_content,
		"rounds": rounds,
		"tools_used": tools_used,
		"error": error_msg,
		"duration": waited,
	}
	_write_result(result)

	print("\n══════════════════════════════════════════════════")
	print("  Done: %d rounds, %d tools, %.1fs" % [rounds, tools_used.size(), waited])
	print("  Result → %s" % RESULT_PATH)
	print("══════════════════════════════════════════════════\n")


# ============ I/O ============

func _read_task() -> String:
	if not FileAccess.file_exists(TASK_PATH):
		return ""
	var f := FileAccess.open(TASK_PATH, FileAccess.READ)
	if f == null:
		return ""
	var json_text := f.get_as_text()
	f.close()

	var parsed: Variant = JSON.parse_string(json_text)
	if typeof(parsed) == TYPE_DICTIONARY:
		return str(parsed.get("task", ""))
	# 也支持纯文本文件
	return json_text.strip_edges()


func _write_result(result: Dictionary) -> void:
	var f := FileAccess.open(RESULT_PATH, FileAccess.WRITE)
	if f:
		f.store_string(JSON.stringify(result, "\t"))
		f.close()
	else:
		push_error("Failed to write result: %s" % RESULT_PATH)


func _write_error(msg: String) -> void:
	print("  ERROR: %s" % msg)
	_write_result({"ok": false, "content": "", "rounds": 0, "tools_used": [], "error": msg, "duration": 0})

extends SceneTree
## Banyan 全工具自动化测试套件 v2 — 无头模式
##
## 运行方式: godot --headless --script tests/test_runner.gd
## 输出: tests/results.json + 终端摘要
##
## 覆盖全部 14 个工具:
## 感知 (8): extract_script_interface, inspect_scene_structured,
##   get_project_architecture, inspect_live_scene, inspect_resource_interface,
##   get_scene_dependencies, analyze_signal_flow, compare_scenes
## 配置 (4): build_scene, patch_scene, configure_resource, configure_project
## 复合 (2): build_script, update_script

const RESULTS_PATH := "res://tests/results.json"
const OUT := "res://tests/_output/"

var results: Array = []
var pass_count: int = 0
var fail_count: int = 0

# Tool module instances
var perception = null
var configuration = null
var composite = null

func _init():
	print("=" .repeat(60))
	print("  Banyan Full Tool Test Suite — Godot %s" % Engine.get_version_info().get("string", ""))
	print("=" .repeat(60))
	print("")

	# Ensure output dir
	if not DirAccess.dir_exists_absolute(OUT):
		DirAccess.make_dir_recursive_absolute(OUT)

	# Load tool modules
	var perc_script = load("res://addons/dotagent/tools/perception_tools.gd")
	var cfg_script = load("res://addons/dotagent/tools/configuration_tools.gd")
	var comp_script = load("res://addons/dotagent/tools/composite_tools.gd")

	if perc_script == null or cfg_script == null or comp_script == null:
		print("FATAL: Cannot load tool modules")
		quit(1)
		return

	perception = perc_script.new()
	configuration = cfg_script.new()
	composite = comp_script.new()

	if perception == null or configuration == null or composite == null:
		print("FATAL: Cannot instantiate tool modules")
		quit(1)
		return

	# === PERCEPTION TOOLS (8) ===
	_run("01_extract_script_interface", _test_extract_script_interface)
	_run("02_inspect_scene_structured", _test_inspect_scene_structured)
	_run("03_get_project_architecture", _test_get_project_architecture)
	_run("04_inspect_live_scene", _test_inspect_live_scene)
	_run("05_inspect_resource_interface", _test_inspect_resource_interface)
	_run("06_get_scene_dependencies", _test_get_scene_dependencies)
	_run("07_analyze_signal_flow", _test_analyze_signal_flow)
	_run("08_compare_scenes", _test_compare_scenes)

	# === CONFIGURATION TOOLS (4) ===
	_run("09_build_scene", _test_build_scene)
	_run("10_patch_scene", _test_patch_scene)
	_run("11_configure_resource", _test_configure_resource)
	_run("12_configure_project", _test_configure_project)

	# === COMPOSITE TOOLS (2) ===
	_run("13_build_script", _test_build_script)
	_run("14_update_script", _test_update_script)

	# Output
	_write_results()
	print("")
	print("=" .repeat(60))
	print("  Results: %d passed / %d failed / %d total" % [pass_count, fail_count, results.size()])
	print("=" .repeat(60))

	# Cleanup
	_cleanup()
	quit(0 if fail_count == 0 else 1)


func _run(name: String, callable: Callable) -> void:
	print("▶ %s ..." % name)
	var result: Dictionary = callable.call()
	result["name"] = name
	results.append(result)
	if result.get("ok", false):
		pass_count += 1
		print("  ✅ PASS: %s" % result.get("detail", ""))
	else:
		fail_count += 1
		print("  ❌ FAIL: %s" % result.get("detail", ""))
		var errs: Array = result.get("data", {}).get("errors", [])
		for e in errs:
			print("     ⚠ %s" % str(e))
	print("")


# ================================================================
#  TEST 01: extract_script_interface
# ================================================================
func _test_extract_script_interface() -> Dictionary:
	var r = perception.call_method("_tool_extract_script_interface", {
		"path": "res://scripts/player.gd",
		"include_private_methods": true
	})
	var ok: bool = r.get("ok", false)
	var data: Dictionary = {}
	if ok:
		data = JSON.parse_string(r.content) if r.content.begins_with("{") else {}
	var errors: Array = []

	if not ok:
		errors.append("Tool returned error: " + r.get("content", ""))
	else:
		if data.get("type", "") != "script_interface":
			errors.append("Wrong type: " + str(data.get("type", "")))
		if data.get("extends", "") != "Area2D":
			errors.append("extends should be Area2D, got: " + str(data.get("extends", "")))

		var sigs: Array = data.get("signals", [])
		var sig_names: Array = sigs.map(func(s): return s.name)
		if not sig_names.has("died"):
			errors.append("Missing signal: died")
		if not sig_names.has("shoot"):
			errors.append("Missing signal: shoot")

		var exps: Array = data.get("exports", [])
		var exp_names: Array = exps.map(func(e): return e.name)
		if not exp_names.has("speed"):
			errors.append("Missing export: speed")

		var pub: Array = data.get("public_methods", [])
		var priv: Array = data.get("private_methods", [])
		if pub.is_empty() and priv.is_empty():
			errors.append("No methods found")

	return _result(errors, data, "%d signals, %d exports, %d pub/%d priv methods" % [
		data.get("signals", []).size(), data.get("exports", []).size(),
		data.get("public_methods", []).size(), data.get("private_methods", []).size()
	])


