		var c = Color(s.color.r, s.color.g, s.color.b, s.color.a * tw)
		draw_circle(s.pos, s.size, c)
		if s.size > 2.0:
			draw_circle(s.pos, s.size * 2.8, Color(c.r, c.g, c.b, c.a * 0.12))



