		Color.from_hsv(fmod(0.60 + hue_shift, 1.0), 0.1, 1.0, 0.85),
		Color.from_hsv(fmod(0.62 + hue_shift, 1.0), 0.05, 1.0, 1.0),
	]
	for i in range(3):
