func _test_partial_grant() -> void:
	var grand := _make_node("Grand", "Ghost", 0)  # 无更上级，自己也没预算
	var mid := _make_node("Mid", "Grand", 4, grand)
	var g: int = await mid.grant_rounds("Child", 10)
	# mid 有 4 < 10 → 向上申请 → grand 无父 → top_up=0 → 只能拨付 4
