func _result(errors: Array, data: Dictionary, detail: String) -> Dictionary:
	if not errors.is_empty():
		data["errors"] = errors
		return {"ok": false, "detail": detail + " | %d errors" % errors.size(), "data": data}
	return {"ok": true, "detail": detail, "data": data}


