func _ready():
	var files = ["res://scripts/player.gd", "res://scripts/boss.gd", "res://scripts/game.gd", "res://scripts/enemy.gd", "res://scripts/audio_manager.gd"]
	for path in files:
		var f = FileAccess.open(path, FileAccess.READ)
		if f == null:
			continue
		var text = f.get_as_text()
		f.close()
		var chunk_size = 3500
		var idx = 0
		var pos = 0
		while pos < text.length():
			var end = mini(pos + chunk_size, text.length())
			var chunk = text.substr(pos, end - pos)
			var out_path = "res://temp_" + path.get_file().get_basename() + "_part" + str(idx) + ".txt"
			var out = FileAccess.open(out_path, FileAccess.WRITE)
			if out == null:
				print("ERR " + out_path + " " + str(FileAccess.get_open_error()))
				break
			out.store_string(chunk)
			out.close()
			idx += 1
			pos = end
	print("SPLIT_DONE")

