func _on_player_shoot_spread(bullet_path, pos, dir):
	var b = load(bullet_path).instantiate()
	b.position = pos
	b.velocity = dir * 700.0
	b.is_enemy = false
	b.color = Color(0.4, 0.95, 1.0)  # 散射用蓝色
