func _generate_sfx(type):
	var rate = 22050.0
	var duration = 0.15
	if type == "shoot":
		duration = 0.09
	elif type == "hit":
		duration = 0.2
	elif type == "explode":
		duration = 0.5
	elif type == "powerup":
		duration = 0.45
	elif type == "click":
		duration = 0.04
	elif type == "damage":
		duration = 0.25
	elif type == "gameover":
		duration = 1.2
	elif type == "wave":
		duration = 0.6
	elif type == "warning":
		duration = 0.5
	else:
		return null
	var frames = int(rate * duration)
	var stream = AudioStreamWAV.new()
	stream.mix_rate = rate
	stream.format = AudioStreamWAV.FORMAT_16_BITS
	stream.stereo = false
	var data = PackedByteArray()
	data.resize(frames * 2)
	var phase = 0.0
	var phase2 = 0.0
	for i in frames:
		var p = float(i) / rate
		var s = 0.0
		if type == "shoot":
			var f = lerp(1400.0, 220.0, p / duration)
			phase += f / rate
			s = sin(phase * TAU) * exp(-p * 28.0) * 0.6
		elif type == "hit":
			var f = lerp(900.0, 120.0, p / duration)
			phase += f / rate
			s = sin(phase * TAU) * exp(-p * 9.0) * 0.5
			s += (randf() * 2.0 - 1.0) * exp(-p * 18.0) * 0.4
		elif type == "explode":
			s = (randf() * 2.0 - 1.0) * exp(-p * 3.5) * (1.0 - p / duration) * 0.7
			s += sin(p * 70.0) * exp(-p * 7.0) * 0.3
		elif type == "powerup":
			var f = 440.0 + 800.0 * (p / duration)
			phase += f / rate
			s = sin(phase * TAU) * exp(-p * 2.5) * 0.6
		elif type == "click":
			s = sin(p * 1600.0) * exp(-p * 90.0) * 0.5
		elif type == "damage":
			s = (randf() * 2.0 - 1.0) * exp(-p * 6.0) * 0.8
