func _process(delta):
	position += velocity * delta
	lifetime -= delta
	if lifetime <= 0 or not _in_bounds():
		queue_free()

func _in_bounds() -> bool:
	var vp = get_viewport_rect()
	return position.x > -50 and position.x < vp.size.x + 50 and position.y > -50 and position.y < vp.size.y + 50

