	var tip = Vector2(0, -16)
	var tail = Vector2(0, 16)
	if is_enemy:
		tip = Vector2(0, 16)
		tail = Vector2(0, -16)
	draw_line(tip, tail, Color(color.r, color.g, color.b, 0.4), 8)
	draw_line(tip, tail, color, 3)
	draw_circle(Vector2(0, 0), 4, color)

