func _on_enemy_killed(value, pos):
	_gm().add_score(value)
	_spawn_explosion(pos, 1.0, Color(1.0, 0.7, 0.2))
	_shake(0.05, 3)
	_hit_spark(pos, Color(1.0, 0.9, 0.3), 0.8)
