func _pick_wave_type(n: int) -> int:
	var roll = randf()
	if n <= 2:
		return 0  # Normal
	if n <= 4:
		return 0 if roll < 0.6 else (1 if roll < 0.85 else 2)
	if n <= 7:
		return 0 if roll < 0.35 else (1 if roll < 0.55 else (2 if roll < 0.75 else (3 if roll < 0.9 else 4)))
