				_hit_spark(b.position, Color(1.0, 1.0, 0.6), 0.5)
				b.queue_free()
				break
	for p in powerups.get_children():
		if not is_instance_valid(p):
			continue
		if player.overlaps_area(p):
			player.apply_powerup(p.powerup_type)
