	if n <= 7:
		return 0 if roll < 0.35 else (1 if roll < 0.55 else (2 if roll < 0.75 else (3 if roll < 0.9 else 4)))
	# Wave 8+
	return 0 if roll < 0.2 else (3 if roll < 0.4 else (4 if roll < 0.6 else (5 if roll < 0.8 else 2)))

